      "claim": "Existing LLM routing work mostly selects one model for an entire request."
    },
    {
      "source_id": "source_006",
      "title": "Task decomposition boundary",
      "content_hash": "96a837f9788f5d0c6d9ab2cc9633775c42dc5569afc70b1782dc1d6d7a198504",
      "claim": "Static task decomposition belongs to the application layer."
    },
